{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Ipratropium bromide, the closest analogue with the same quaternary ammonium tropane tropate ester scaffold, has an absolute oral bioavailability of only 2.0% in healthy volunteers, directly supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tiotropium, another quaternary ammonium tropane with the epoxide-bridged scaffold, has an absolute oral bioavailability of only 2–3% from an oral solution in healthy volunteers, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Phenoperidine, a basic amine opioid, had systemic bioavailability of only 9.9–13.9% after oral administration, supporting low oral bioavailability for ionizable/basic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Tropisetron, a tertiary-amine tropane ester, can show high oral bioavailability (up to 100% at 45 mg), indicating that the tropane ester motif alone does not mandate low F; however, the query's permanent quaternary ammonium charge is the key difference and this evidence has low transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a permanently charged quaternary ammonium tropane ester. The closest experimental analogues, ipratropium and tiotropium, are also quaternary ammonium tropanes and show absolute oral bioavailability of only 2–3% in humans. This direct, threshold-relevant evidence strongly outweighs less transferable high-bioavailability data from tertiary-amine or neutral analogues, so the query is predicted to have low oral bioavailability (<20%).",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability data exist for the exact query molecule.",
    "High-bioavailability evidence comes from structurally less similar tertiary amines or neutral esters and does not address the quaternary ammonium absorption barrier."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

